CREATE OR REPLACE PROCEDURE sp(arg1 VARCHAR2, arg2 NUMBER, arg3 VARCHAR2, arg4 VARCHAR2) AS
  v_mascot_count NUMBER;
  v_updated_count NUMBER := 0;
  v_budget_avg NUMBER;
  v_enrollment_avg NUMBER;
BEGIN
  SAVEPOINT sp_savepoint;

  SELECT COUNT(*)
    INTO v_mascot_count
    FROM "School"
   WHERE "Mascot" = arg3;

  IF v_mascot_count = 0 THEN
    RAISE_APPLICATION_ERROR(-20002, 'No School record matches the mascot; budget updates skipped');
  END IF;

  SELECT AVG("Budgeted")
    INTO v_budget_avg
    FROM "budget";

  SELECT AVG("Enrollment")
    INTO v_enrollment_avg
    FROM "School";

  UPDATE "budget"
     SET "total_budget_percent_budgeted" = arg2
   WHERE "Budget_invested_percent" = arg1
     AND "total_budget_percent_budgeted" <= arg2
     AND "Budgeted" > v_budget_avg;

  v_updated_count := v_updated_count + SQL%ROWCOUNT;

  UPDATE "School"
     SET "Location" = arg4
   WHERE "Mascot" = arg3
     AND "Enrollment" > v_enrollment_avg;

  v_updated_count := v_updated_count + SQL%ROWCOUNT;

  IF v_updated_count = 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'No matching records were updated');
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK TO sp_savepoint;
    RAISE;
END;

